const safe = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const strip = (h) => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/g, ' ').replace(/\s+/g, ' ').trim();
const jobs = [];
const add = (source, title, company, url, date, text, apply, loc) => {
  if (title && url) jobs.push({ source, title: String(title), company: company || '', url, apply_url: apply || url, date, loc: [].concat(loc || []).join(' '), text: strip(text).slice(0, 1500) });
};
safe('Remotive').forEach(r => (r.jobs || []).forEach(j => add('Remotive', j.title, j.company_name, j.url, j.publication_date, (j.description || '') + ' ' + (j.tags || []).join(' '), null, j.candidate_required_location)));
safe('RemoteOK').forEach(j => { if (j.position) add('RemoteOK', j.position, j.company, j.url, j.date, (j.description || '') + ' ' + (j.tags || []).join(' '), j.apply_url, j.location); });
safe('Himalayas').forEach(r => (r.jobs || []).forEach(j => add('Himalayas', j.title, j.companyName, j.applicationLink || j.guid, j.pubDate ? new Date(Number(j.pubDate) * 1000).toISOString() : null, (j.excerpt || '') + ' ' + (j.categories || []).join(' '))));
safe('Jobicy').forEach(r => (r.jobs || []).forEach(j => add('Jobicy', j.jobTitle, j.companyName, j.url, j.pubDate, (j.jobExcerpt || '') + ' ' + [].concat(j.jobIndustry || []).join(' '), null, j.jobGeo)));
safe('Arbeitnow').forEach(r => (r.data || []).forEach(j => { if (j.remote) add('Arbeitnow', j.title, j.company_name, j.url, j.created_at ? new Date(Number(j.created_at) * 1000).toISOString() : null, (j.description || '') + ' ' + (j.tags || []).join(' ')); }));
safe('Working Nomads').forEach(j => add('Working Nomads', j.title, j.company_name, j.url, j.pub_date, (j.description || '') + ' ' + (j.tags || '') + ' ' + (j.category_name || ''), null, j.location));
safe('Remotive n8n and no-code').forEach(r => (r.jobs || []).forEach(j => add('Remotive', j.title, j.company_name, j.url, j.publication_date, (j.description || '') + ' ' + (j.tags || []).join(' '))));
safe('Jobspresso').forEach(j => add('Jobspresso', j.title, '', j.link, j.isoDate || j.pubDate, j.contentSnippet || j.content));
safe('We Work Remotely').forEach(j => {
  const t = String(j.title || '');
  const idx = t.indexOf(':');
  add('We Work Remotely', idx > -1 ? t.slice(idx + 1).trim() : t, idx > -1 ? t.slice(0, idx).trim() : '', j.link, j.isoDate || j.pubDate, j.contentSnippet || j.content);
});
const kw = /(n8n|automation|automate|zapier|make\.com|integromat|no[- ]?code|low[- ]?code|workflow|\bai\b|artificial intelligence|llm|prompt|agentic|rpa|chatbot|gpt|implementation specialist)/i;
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
const okLoc = /(worldwide|anywhere|global|africa|nigeria|emea|international|any location|all countries)/i;
const badText = /(us only|usa only|u\.s\. only|must (reside|be located|live) in (the )?(us|usa|united states|uk|canada|eu)|us citizens?|work authori[sz]ation|green card|eu only|uk only|canada only)/i;
const blockedLoc = /(usa|united states|u\.s\.|canada|uk|united kingdom|europe|germany|france|australia|india|philippines|latam|latin america|brazil|mexico|spain|poland|netherlands|ireland|israel|singapore)/i;
const seen = new Set();
const out = [];
for (const j of jobs) {
  if (seen.has(j.url)) continue;
  if (j.loc && !okLoc.test(j.loc) && blockedLoc.test(j.loc)) continue;
  if (badText.test(j.title + ' ' + j.text)) continue;
  seen.add(j.url);
  const ts = j.date ? new Date(j.date).getTime() : NaN;
  if (!isNaN(ts) && ts < cutoff) continue;
  if (!kw.test(j.title + ' ' + j.text)) continue;
  out.push({ json: j });
}
return out;

