const jobs = $('Limit').all();
const out = [];
$input.all().forEach((item, i) => {
  const j = jobs[i].json;
  let raw = (item.json.content && item.json.content.parts && item.json.content.parts[0] && item.json.content.parts[0].text) || item.json.output || item.json.text || item.json;
  let p = {};
  if (typeof raw === 'string') {
    raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
    try { p = JSON.parse(raw); } catch (e) { p = { score: 5, summary: raw.slice(0, 200) }; }
  } else { p = raw; }
  const score = Number(p.score) || 0;
  if (score < 5) return;
  if (p.accepts_nigeria === false || String(p.accepts_nigeria).toLowerCase() === 'false') return;
  const em = (String(j.text || '') + ' ' + String(p.next_steps || '')).match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  out.push({ json: { ...j, apply_email: em ? em[0] : '', score, summary: p.summary || '', why_fit: p.why_fit || '', next_steps: p.next_steps || 'Apply via link', cover_letter: p.cover_letter || '', found_at: new Date().toISOString() } });
});
out.sort((a, b) => b.json.score - a.json.score);
return out;

